        ["LICHT"] = "LIGHT",
        ["Helligkeit"] = "Brightness",
        ["Hellt die Mitten auf oder dunkelt sie ab. Schwarz und Weiß bleiben, nichts frisst aus."] = "Brightens or darkens the midtones. Black and white stay, nothing blows out.",
        ["Kontrast"] = "Contrast",
        ["Rechts: Helles heller, Dunkles dunkler — knackiger. Links: weicher, flacher."] = "Right: brights brighter, darks darker — punchier. Left: softer, flatter.",
        ["Tiefen"] = "Shadows",
        ["Rechts: dunkle Bereiche aufhellen, z. B. Gesichter im Gegenlicht. Wirkt nur dort, wo die Umgebung dunkel ist — helle Bereiche bleiben."] = "Right: brighten dark areas, e.g. backlit faces. Only works where the surroundings are dark — bright areas stay.",
        ["Lichter"] = "Highlights",
        ["Links: helle Bereiche abdunkeln und Zeichnung zurückholen, z. B. im Himmel. Wirkt nur dort, wo die Umgebung hell ist."] = "Left: darken bright areas and recover detail, e.g. in the sky. Only works where the surroundings are bright.",
        ["Dunst"] = "Dehaze",
        ["DUNST"] = "DEHAZE",
        ["Durchläufe"] = "Passes",
        ["Wie oft der Dunst nacheinander entfernt wird — wie das Auge: Ergebnis ansehen, wieder schätzen. Jeder Durchlauf ist ein sachter Schritt mit Kontrast, Dynamik und Schärfe aus dieser Gruppe; der nächste schätzt den klareren Stand neu. Mehr Durchläufe wirken kräftiger. Vorgabe 3; der Himmel bleibt ab dem zweiten unverändert."] = "How many times the haze is removed in succession — like the eye: look at the result, estimate again. Each pass is a gentle step with contrast, vibrance and sharpening from this group; the next one re-estimates the clearer result. More passes act more strongly. Default 3; the sky stays unchanged from the second pass on.",
        ["Klarheit"] = "Clarity",
        ["Lokaler Kontrast mit großem Radius, kantentreu — Strukturen in der Ferne treten hervor. Nicht im Himmel."] = "Local contrast with a large radius, edge-preserving — structures in the distance stand out. Not in the sky.",
        ["Sanfte S-Kurve auf der Helligkeit nach dem Entfernen."] = "Gentle S-curve on brightness after removal.",
        ["Blasse Farben (Ferne) bekommen mehr Buntheit, kräftige kaum. Nicht im Himmel."] = "Pale colours (distance) get more chroma, strong ones hardly any. Not in the sky.",
        ["Schärfe fein"] = "Fine sharpen",
        ["Feine Schärfe (3 × 3 Pixel) auf der Landschaft — Details, die der Dunst verschluckt hat."] = "Fine sharpening (3 × 3 pixels) on the landscape — details the haze swallowed.",
        ["Kanten"] = "Edges",
        ["Kantenschärfe mit größerem Radius (2 Pixel), je Durchlauf. Vorgabe aus — erst, wenn die feine Schärfe nicht reicht."] = "Edge sharpening with a larger radius (2 pixels), in each pass. Off by default — only when fine sharpening is not enough.",
        ["Wie weit die Helligkeit großräumig wieder ans Original angeglichen wird. 100: so hell wie vorher; 0: so dunkel, wie die Szene ohne Dunst wäre."] = "How far the large-scale brightness is matched back to the original. 100: as bright as before; 0: as dark as the scene would be without haze.",
        ["Entstufen"] = "Deband",
        ["Glättet Treppen in weichen Verläufen wie dem Himmel (Debanding): am Original, bevor der Kontrast die 8-Bit-Stufen spreizt, und nach jedem Durchlauf. Kanten und Struktur bleiben. Gerechnet wird ohnehin in 32 Bit, auf 8 Bit gerundet erst am Schluss, mit feinem Korn."] = "Smooths steps in soft gradients such as the sky (debanding): on the original, before contrast spreads the 8-bit levels apart, and after every pass. Edges and texture stay. Processing is in 32 bit anyway, rounded to 8 bit only at the end, with fine grain.",
        ["Vorgaben"] = "Defaults",
        ["Feineinstellung zurück auf die Vorgaben (3 Durchläufe). Der Dunst-Regler bleibt."] = "Fine settings back to the defaults (3 passes). The dehaze slider stays.",
        ["Rechts: Dunst und Nebel entfernen — ferne Berge, Stadt im Smog, Aufnahmen durchs Fenster bekommen wieder Kontrast und Farbe. Bis 100 so viel, wie physikalisch geschätzt wird, darüber kräftiger (bis 300). Links: Dunst hinzufügen, für eine weiche Stimmung."] = "Right: remove haze and fog — distant mountains, a city in smog, shots through a window get their contrast and colour back. Up to 100 as much as is physically estimated, above that stronger (up to 300). Left: add haze for a soft mood.",
        ["FARBE"] = "COLOUR",
        ["Sättigung"] = "Saturation",
        ["Dynamik"] = "Vibrance",
        ["Rechts: blasse Farben kräftiger, schon kräftige kaum — Hauttöne bleiben natürlich. Lebendiger als Sättigung, ohne bunt zu wirken."] = "Right: muted colours get stronger, already strong ones hardly change — skin tones stay natural. More lively than saturation without looking garish.",
        ["Rechts: alle Farben gleich stark kräftiger. Ganz links: Schwarzweiß."] = "Right: all colours equally stronger. All the way left: black and white.",
        ["Färben"] = "Tint",
        ["Das ganze Bild in einem Farbton: Schwarzweiß oder eine Farbe nach Wahl — z. B. Sepia wie ein alter Fotoabzug."] = "The whole image in one tone: black and white or a colour of your choice — e.g. sepia like an old photo print.",
        ["Farbton"] = "Hue",
        ["Farbe der Tönung. Um 30°: Sepia, um 210°: kühles Blau."] = "Colour of the tint. Around 30°: sepia, around 210°: cool blue.",
        ["Aus"] = "Off",
        ["Schwarzweiß"] = "Black and white",
        ["GLEICHE FARBE"] = "MATCH COLOUR",
        ["Luminanz"] = "Luminance",
        ["Wie „Gleiche Farbe“ in Referenzwerkzeug CS5: rechnet die Helligkeit hoch statt sie nur anzuheben — das Bild wird leuchtender, die Kontraste bleiben. Weiß läuft weich aus, nichts frisst aus."] = "Like “Match Color” in Referenzwerkzeug CS5: scales the brightness up instead of just lifting it — the image becomes more luminous and the contrasts stay. White rolls off softly, nothing blows out.",
        ["Ausgleichen"] = "Neutralise",
        ["Entfernt einen Farbstich (z. B. gelbes Kunstlicht, blauer Schatten): Graues und Weißes wird wieder neutral. Der Regler bestimmt, wie viel davon. Kräftige Farben zählen bei der Erkennung nicht mit."] = "Removes a colour cast (e.g. yellow artificial light, blue shade): greys and whites become neutral again. The slider sets how much. Strong colours are not counted when detecting the cast.",
        ["Links kühler (bläulich), rechts wärmer (gelblich), Mitte neutral — z. B. wenn Ausgleichen ein Kunstlicht-Foto zu kühl gemacht hat."] = "Left cooler (bluish), right warmer (yellowish), centre neutral — e.g. when neutralising made an artificial-light photo too cool.",
